from __future__ import absolute_import
from lxml import etree
from robot.api import logger

from .ql_file import QualityLevel


class SiteconfParser():
    """

    """

    def __init__(self):
        self.ql_object = QualityLevel()

    def check_if_param_status(self, siteconf, param, status):
        """
        Checks if parameter has proper status.

        *AUTHOR* sebastian.burniak@nokia.com

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | siteconf           | Yes    | path to siteconf file                 |
        +--------------------+--------+---------------------------------------+
        | param              | Yes    | parameter to be checked               |
        +--------------------+--------+---------------------------------------+
        | status             | Yes    | expected parameter status             |
        +--------------------+--------+---------------------------------------+

        *RETURN VALUE*
        -  bool
        """
        all_params = self.get_all_found_params_from_siteconf_by_tag(siteconf,
                                                                    param)
        if not all_params:
            logger.error("Not found any parameters by tag in siteconf file")
            return False
        for param in all_params:
            if param.text != status:
                logger.info(
                    ("{} parameter is wrong: "
                     "{} != {}").format(param.tag, param.text, status),
                    also_console=True)
                return False
        logger.info("{} parameter is OK: {} = {}".format(param.tag, param.text,
                                                         status),
                    also_console=True)
        return True

    def check_if_cells_states(self, siteconf, parameters):
        """
        Checks if cells parameters are ok.

        *AUTHOR* sebastian.burniak@nokia.com

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | siteconf           | Yes    | path to siteconf file                 |
        +--------------------+--------+---------------------------------------+
        | parameters         | Yes    | working or blocked                    |
        |                    |        | depends on status to be checked       |
        +--------------------+--------+---------------------------------------+

        *RETURN VALUE*
        -  bool
        """
        all_cells = self.get_all_found_params_from_siteconf_by_tag(siteconf,
                                                                   "Cell")
        for cell in all_cells:
            for key, value in parameters.items():
                if not self.is_in_dedicated_state(key, value, cell):
                    return False
        return True

    def check_if_units_states(self, siteconf, parameters, unit_list):
        """
        Checks if units parameters are ok.

        *AUTHOR* sebastian.burniak@nokia.com

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | siteconf           | Yes    | path to siteconf file                 |
        +--------------------+--------+---------------------------------------+
        | parameters         | Yes    | working or blocked                    |
        |                    |        | depends on status to be checked       |
        +--------------------+--------+---------------------------------------+

        *RETURN VALUE*
        -  bool
        """
        destination_units = self._get_destination_units(siteconf, unit_list)
        for key, value in parameters.items():
            for unit in destination_units:
                if (not self.is_in_dedicated_state(key, value, unit)) \
                        and self.search_for_degraded_state(unit):
                    return False
        return True

    def _get_destination_units(self, siteconf, *args):
        all_elem = self.get_all_found_params_from_siteconf_by_tag(siteconf,
                                                                  "Unit")
        destination_units = []
        for elem in all_elem:
            try:
                if elem.xpath(".//_logicalId/text()")[0] in args[0]:
                    destination_units.append(elem)
            except IndexError as e:
                logger.info(e)
        return destination_units

    def search_for_degraded_state(self, unit_obj):
        """
        Searches for degraded state in _state parameter.

        *AUTHOR* sebastian.burniak@nokia.com

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | unit_obj           | Yes    | xml object to check                   |
        |                    |        | if '_state' equals 'degraded'         |
        +--------------------+--------+---------------------------------------+

        *RETURN VALUE*
        -  bool
        """
        unit_id = self._get_unit_id(unit_obj)
        state = self._get_state(unit_obj)
        logger.info(
            "Checking if {unit} is in degraded state".format(unit=unit_id))
        msg_pattern = "{unit} is in {state} state."
        msg_with_all_info = msg_pattern.format(
            unit=unit_id,
            state=unit_obj.findall(".//_state")[0].text
        )
        if state == "degraded":
            self._handle_degraded_state(msg_pattern, msg_with_all_info)
            return True
        elif state != "working":
            self._handle_not_working_state(msg_with_all_info, unit_id)
        logger.info(msg_pattern + " NOT DEGRADED", also_console=True)
        return False

    def _handle_degraded_state(self, msg_pattern, msg_with_all_info):
        logger.error(msg_with_all_info)
        self.ql_object.add_new_ql('QL2', msg_pattern)

    def _handle_not_working_state(self, msg_with_all_info, unit_id):
        logger.info(msg_with_all_info)
        self.ql_object.add_new_ql('QL3', "{unit} is in {state} state".format(
            unit=unit_id, state="DEGRADED"))

    def _get_unit_id(self, unit_obj):
        unit_id = unit_obj.find(
            ".//_logicalId").text if unit_obj.tag == 'Unit' else unit_obj.find(
            ".//_id").text
        return unit_id

    def _get_state(self, unit_obj):
        state = unit_obj.find(".//_state").text
        return state

    @staticmethod
    def get_all_found_params_from_siteconf_by_tag(siteconf, parameter_to_find):
        """
        Returns parameters from siteconf found by text.

        *AUTHOR* sebastian.burniak@nokia.com

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | siteconf           | Yes    | path to siteconf file                 |
        +--------------------+--------+---------------------------------------+
        | parameter_to_find  | Yes    | search in xml to find                 |
        |                    |        | objects by expected tag               |
        +--------------------+--------+---------------------------------------+

        *RETURN VALUE*
        - list of found xml objects
        """
        try:
            tree = etree.parse(siteconf)
        except Exception as e:
            logger.error(e)
        else:
            root = tree.getroot()
            return root.findall(
                ".//{parameter}".format(parameter=parameter_to_find))

    def is_in_dedicated_state(self, param, expected_state, obj_to_check):
        """
        Checks if parameter has dedicated state
        SWBT - support

        *AUTHOR* sebastian.burniak@nokia.com

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | param              | Yes    | parameter to be check                 |
        +--------------------+--------+---------------------------------------+
        | expected_state     | Yes    | State to be compared                  |
        +--------------------+--------+---------------------------------------+
        | obj_to_check       | Yes    | Xml object to find in                 |
        +--------------------+--------+---------------------------------------+

        *RETURN VALUE*
        - bool:
        """
        obj_id = self._find_id(obj_to_check)
        param_state = \
            obj_to_check.findall(".//{parametr}".format(parametr=param))[
                0].text
        state_equals_expectation = (param_state == expected_state)
        self._log_param_verdict(expected_state, obj_id, param, param_state,
                                state_equals_expectation)
        return state_equals_expectation

    @staticmethod
    def _find_id(obj_to_check):
        if obj_to_check.tag == 'Unit':
            obj_id = obj_to_check.find(".//_logicalId").text
        else:
            obj_id = "cell {}".format(obj_to_check.find(".//_id").text)
        return obj_id

    @staticmethod
    def _log_param_verdict(expected_state, obj_id, param, param_state,
                           state_equals_expectation):
        msg_pattern = ("{param} parameter status in {id}"
                       " {verdict} expected: {actual} == {expected}")
        verdict = "is equal" if state_equals_expectation else "is NOT equal"
        msg = msg_pattern.format(param=param, id=obj_id, verdict=verdict,
                                 actual=param_state, expected=expected_state)
        logger.info(msg)

    def get_num_configured_devices(self, siteconf, device, unit_list):
        """
        Returns number of already configured devices
        SWBT - support

        *AUTHOR* sebastian.burniak@nokia.com

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | siteconf           | Yes    | path to siteconf file                 |
        +--------------------+--------+---------------------------------------+
        | device             | Yes    | SM or RM to count how many configured |
        +--------------------+--------+---------------------------------------+

        *RETURN VALUE*
        - num of configured devices
        """
        devices = self._get_devices(device, unit_list)
        devices_parameters = [
            self.get_all_found_params_from_siteconf_by_text(siteconf, params)
            for params in devices
        ]
        configured_devices = [params for params in devices_parameters if
                              params]
        return len(configured_devices)

    def _get_devices(self, device, unit_list):
        if device == "SM":
            return self._get_fsm_devices(unit_list)
        elif device == "RM":
            return self._get_fr_devices(unit_list)
        else:
            logger.error("Did not properly specified 'device' "
                         "argument. Must be 'SM' or 'RM'")
            return []

    def _get_fsm_devices(self, unit_list):
        return [fsm for fsm in unit_list if
                fsm.startswith("FSM") and not fsm.endswith("FT")]

    def _get_fr_devices(self, unit_list):
        return [frm for frm in unit_list if frm.startswith("FR")]

    @staticmethod
    def get_all_found_params_from_siteconf_by_text(siteconf, text_to_find):
        """
        Returns parameters from siteconf found by text.

        *AUTHOR* sebastian.burniak@nokia.com

        +--------------------+--------+---------------------------------------+
        | Input Parameters   | Man.   | Description                           |
        +====================+========+=======================================+
        | siteconf           | Yes    | path to siteconf file                 |
        +--------------------+--------+---------------------------------------+
        | text_to_find       | Yes    | Search in xml to find objects         |
        |                    |        | '_logicalId' by expected text         |
        +--------------------+--------+---------------------------------------+

        *RETURN VALUE*
        - list of found xml objects
        """
        try:
            tree = etree.parse(siteconf)
        except Exception as e:
            logger.error(e)
        else:
            root = tree.getroot()
            return root.xpath(
                './/_logicalId[text()="{}"]'.format(text_to_find))
